#include <stdio.h>

#define S_BITS 2          /* S = 4 sets   */
#define B_BITS 1          /* B = 2 bytes  */
#define NSETS (1 << S_BITS)

static int valid[NSETS];
static unsigned tag_of_set[NSETS];

/* Split a byte address into (tag, set, block-offset) for this cache. */
static void decompose(unsigned addr, unsigned *tag, unsigned *set, unsigned *off) {
    *off = addr & ((1u << B_BITS) - 1);
    *set = (addr >> B_BITS) & (NSETS - 1);
    *tag = addr >> (B_BITS + S_BITS);
}

static char access_byte(unsigned addr) {
    unsigned tag, set, off;
    decompose(addr, &tag, &set, &off);
    if (valid[set] && tag_of_set[set] == tag)
        return 'h';
    valid[set] = 1;
    tag_of_set[set] = tag;
    return 'm';
}

int main(void) {
    char grid[5][5];
    int hits = 0, misses = 0;

    /* char matrix[5][5] at address 0, summed column-wise: col outer, row inner. */
    for (int col = 0; col < 5; col++)
        for (int row = 0; row < 5; row++) {
            char r = access_byte((unsigned) (5 * row + col));
            grid[row][col] = r;
            if (r == 'h') hits++; else misses++;
        }

    for (int row = 0; row < 5; row++) {
        for (int col = 0; col < 5; col++)
            putchar(grid[row][col]), putchar(' ');
        putchar('\n');
    }
    printf("hits=%d misses=%d miss_rate=%.0f%%\n",
           hits, misses, 100.0 * misses / (hits + misses));
    return 0;
}
